const [respuesta, setRespuesta] = useState(null);
const [cargando, setCargando] = useState(true);
const [error, setError] = useState(null);

useEffect(() => {
  let ignorar = false;
  setCargando(true);
  setError(null);
  fetch(`/api/practica/productos?pagina=${pedido.pagina}&limite=10`)
    .then((r) => { if (!r.ok) throw new Error(`Error ${r.status}`); return r.json(); })
    .then((cuerpo) => { if (!ignorar) { setRespuesta(cuerpo); setCargando(false); } })
    .catch((e) => { if (!ignorar) { setError(e.message); setCargando(false); } });
  return () => { ignorar = true; };
}, [pedido]);

